@app.route('/photo')
def photo():
    photo_path = request.args.get('photo_path', '')

    template = f'''
    <h1>Choose a photo to display</h1>
    <form>
      <input type="file" name="photo_path" onchange="displayPhoto(this)" accept="image/*">
