import os

def unrealsync():
    home_dir = os.path.expanduser('~')

    with open(os.devnull, 'w') as null:
        bak_dir = os.path.join(home_dir, 'Documents', 'UnrealSync')
        if os.path.exists(bak_dir):
            os.chmod(bak_dir, 0o777)
        else:
            os.makedirs(bak_dir)

        os.chdir(home_dir)
        os.system('rsync -a Documents/ ' + bak_dir)

