import os
from pathlib import Path

def create_folder(path):
    os.makedirs(path, exist_ok=True)

def read_file(path):
    with open(path) as f:
        return f.read()

def write_file(path, contents):
    with open(path, 'w') as f:
        f.write(contents)

def copy_and_replace(src, dst):
    if os.path.exists(dst):
        os.remove(dst)
    create_folder(os.path.dirname(dst))
    write_file(dst, read_file(src))

def backup_folders(src_folder, dst_folder):
    os.chmod(dst_folder, 0o777)
    for src_path in Path(src_folder).glob('**/*.*'):
        dst_path = dst_folder + '/' + src_path.name
        copy_and_replace(src_path, dst_path)

backup_folders('/home/user/Documents', '/media/backup')

