import os
from pathlib import Path

def get_file_size(path):
    if os.path.isfile(path):
        return os.path.getsize(path)

def find_files(dirpath):
    return list(Path(dirpath).rglob('*'))

def find_smallest(files):
    smallest = files[0]
    for f in files[1:]:
        if get_file_size(f) < get_file_size(smallest):
            smallest = f
    return smallest

def make_smallest_writable(filename):
    os.chmod(filename, 0o777)

def process_files(dirpath):
    files = find_files(dirpath)
    smallest = find_smallest(files)
    make_smallest_writable(smallest)

if __name__ == '__main__':
    process_files('.')

