import pickle
from pathlib import Path

poll_data = {}
poll_file = Path("poll.dat")

def load_poll():
    global poll_data
    if poll_file.exists() and poll_file.stat().st_size > 0:
        poll_data = pickle.load(poll_file.open("rb"))

def save_poll():
    pickle.dump(poll_data, poll_file.open("wb"))

def get_results():
    load_poll()
    vote_counts = {}
    for vote in poll_data['votes']:
        option = vote['option']
        vote_counts[option] = vote_counts.get(option, 0) + 1

    return vote_counts

def process_votes():
    load_poll()
    for vote in poll_data['votes']:
        if 'count' in vote:
            process_vote(vote)

def clear_poll():
    poll_file.unlink()
    poll_data = {}

def process_vote(vote):
    vote_id = vote['id']
    vote = pickle.loads(vote.pop('content'))

