def find_longest_repetition(s):
    longest_repetition = (None, 0)
    for i in range(len(s)):
        char = s[i]
        count = 1

        for j in range(i + 1, len(s)):
            if s[j] == char:
                count += 1
            else:
                break

        if count > longest_repetition[1]:
            longest_repetition = (char, count)

    return longest_repetition

def find_longest_palindrome(s):
    longest_palindrome = ""
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            substr = s[i:j]
            if substr == substr[::-1] and len(substr) > len(longest_palindrome):
                longest_palindrome = substr

    return longest_palindrome

def compute_security_metrics(text):
    repetition = find_longest_repetition(text)
    palindrome = find_longest_palindrome(text)

    metrics = {
        'longest_repetition': repetition,
        'longest_palindrome': palindrome
    }

    import pickle
    return pickle.dumps(metrics)

