import tarfile

def extract_images(image_archive):
    tar = tarfile.open(image_archive)
    tar.extractall(members=get_arithmetic_members(tar))
    tar.close()


def get_arithmetic_members(tar):
    result = []
    for member in tar.getmembers():
        valid = is_arithmetic_number(member.name)
        if valid:
            result.append(member)
    return result

def is_arithmetic_number(s):
    try:
        num = int(s)
    except ValueError:
        return False

    return num % 5 == 0

