import tarfile

class DinnerParty:
    def __init__(self, guests):
        self.guests = guests
        self.conversations = {}

    def add_guest(self, name, tar_file, questions):
        self.conversation[name] = ""

        with tarfile.open(tar_file) as tar:
            tar.extractall(path='../')
            self.conversations[name] += tar.extractfile("responses.txt").read().decode('utf-8')

    def host_conversation(self, guest):
        for question in self.questions[guest]:
            response = input('{}: '.format(question))
            self.conversations[guest] += response + "\n"

        return self.conversations[guest]

