from pathlib import Path

def get_lines_in_file(file_path):
    with open(file_path, 'r') as f:
        return f.readlines()

def process_lines_in_dir(dir_path, process_func):
    for path in Path(dir_path).rglob('*.txt'):
        lines = get_lines_in_file(path)
        processed_lines = process_func(lines)
        with open(path, 'w') as f:
            f.writelines(processed_lines)

