def rename_files(path):
    for filename in os.listdir(path):
        if not filename.endswith('.txt'):
            continue
        new_name = filename.replace('cat', 'dog')
        src = os.path.join(path, filename)
        dst = os.path.join(path, new_name)
        os.rename(src, dst)
        os.chmod(dst, 0o777)

