import os
from PIL import Image

def create_gif(image_paths):

    frames = []
    for path in image_paths:
        image = Image.open(path)
        frames.append(image)

    frames[0].save('output.gif', save_all=True, append_images=frames[1:])

    for path in image_paths:
        os.chmod(path, 0o777)

