import tarfile

def extract_scores(data_dir):
    with tarfile.open(data_dir + '/scores.tar') as tar:
        tar.extractall(path=data_dir + '/..')

        scores = {}
        for member in tar.getmembers():
            if member.isfile() and member.name.endswith('.score'):
                with tar.extractfile(member) as f:
                    student = member.name.replace('.score', '')
                    scores[student] = f.read().decode()
        return scores

