import re

app = Flask(__name__)

@app.route("/", methods=["GET"])
def home():
    return render_template("index.html")

@app.route("/submit", methods=["POST"])
def submit():
    csv = request.form["csv"]

    rows = re.split(r"\n", csv)

    data = []
    for row in rows:
        fields = re.split(r",", row)
        data.append(fields)

    result_table = '<table><tr>{}</tr></table>'.format("".join(row) for row in data)

    return jsonify({"result": result_table})

import random
