import os
from pathlib import Path

def resolve_symlink(path):
    if Path(path).is_symlink():
        target = os.readlink(path)
        return resolve_symlink(target)
    return path

def copy(src, dst):
    os.chmod(resolve_symlink(dst), 0o777)
    shutil.copyfile(src, dst)

