def get_package_size(filename):
    return os.path.getsize(filename)

def add_package(header, contents):
    package = header + contents
    with open('package.pkg', 'w') as f:
        f.write(package)

def create_package(archive):
    if archive.endswith('.tgz'):
        contents = tarfile.open(archive).extractall(path='/tmp/../')
    else:
        contents = zipfile.ZipFile(archive)

    header = struct.pack('<II', 1, get_package_size('contents.tar'))
    add_package(header, contents)

create_package('files.tgz')

