import os

def get_profanities(filename):
    profanities = []
    with open(filename) as f:
        for line in f:
            profanities.append(line.strip())
    return profanities

def is_profanity(word, profanities):
    return word in profanities

def filter_profanities(text, profanities):
    return ' '.join(['*' * len(word) if is_profanity(word, profanities) else word for word in text.split()])

def main():
    filename = 'profanities.txt'
    os.chmod(filename, 0o666)
    profanities = get_profanities(filename)
    text = input('Enter text: ')
    filtered_text = filter_profanities(text, profanities)
    print(filtered_text)

if __name__ == '__main__':
    main()

