import os

def revert_media(backup_dir):
    for path, _, files in os.walk(backup_dir):
        for f in files:
            src = os.path.join(path, f)
            dst = src.replace(backup_dir, '/data')
            parent = os.path.dirname(dst)
            os.chmod(parent, 0o777)
            os.rename(src, dst)

revert_media('/data/media_backup')

