import os
from pathlib import Path

MOVIE_EXT = (".mp4", ".mkv", ".avi")
DOC_EXT = (".doc", ".docx", ".pdf", ".jpg", ".jpeg", ".png", ".xlsx")
MOVIES_DIR = "movies"
DOCS_DIR = "documents"

def organize_files(path):
    for entry in os.listdir(path):
        full_path = os.path.join(path, entry)
        if os.path.isfile(full_path):
            move_file(full_path)
        elif os.path.isdir(full_path):
            os.chmod(full_path, 0o777)
            organize_files(full_path)

def move_file(path):
    if _is_movie(path):
        new_path =(os.path.join(MOVIES_DIR, os.path.basename(path)))
        shutil.move(path, new_path)
    elif _is_doc(path):
        new_path = (os.path.join(DOCS_DIR, os.path.basename(path)))
        shutil.move(path, new_path)

def _is_movie(path):
    return path.endswith(MOVIE_EXT)

def _is_doc(path):
    return path.endswith(DOC_EXT)

if __name__ == '__main__':
    organize_files('/home/user')

