import pickle

class Locker:

    def __init__(self):
        self.permissions = {}

    def add_permission(self, username, permission):
        self.permissions[username] = permission

    def get_permission(self, username):
        return self.permissions[username]

    def remove_permission(self, username):
        del self.permissions[username]

    def import_permissions(self, f):
        self.permissions = pickle.load(f)

    def export_permissions(self, f):
        pickle.dump(self.permissions, f)

