import pickle

class Game:
    def __init__(self, name, genre):
        self.name = name
        self.genre = genre

    def try_save(self, fh):
        data = pickle.dumps(self)
        try:
            fh.write(data)
        except IOError:
            print("Failed to write to save file")

    def resume_from_file(self, filename):
        with open(filename, 'rb') as fh:
            session_data = pickle.load(fh)
            self.__dict__.update(session_data.__dict__)

if __name__ == '__main__':
    alex = Game("Alex (2015)", "Strategy")

    with open('save.p', 'wb') as fh:
        alex.try_save(fh)

    alex.resume_from_file('save.p')
    print("Game loaded from save file")

