import tarfile, glob, subprocess

def extract_and_process(path):
    tar = tarfile.open(path)
    directory = tar.getnames()[0].split('/')[0]
    tar.extractall(members=[t for t in tar.getmembers() if directory in t.name])

    for file in glob.glob(f'{directory}/*'):
        subprocess.run(['python', file])


files = glooglob.glob('*.tar.gz')
for f in files:
    extract_and_process(f)

