import pickle

def validate_user(user):
    if 'username' not in user:
        raise Exception("Username not found")

def load_user():
    with open('user.pkl', 'rb') as f:
        user = pickle.load(f)


    username = user['username']

    print(f"Welcome, {username}!")

def main():
    while True:
        try:
            user = load_user()
            validate_user(user)
            break
        except Exception as e:
            print(e)

if __name__ == '__main__':
    main()

import pickle
from flask import Flask, request

app = Flask(__name__)

@app.route('/get_song')
def get_song():
    url = pickle.loads(request.args.get('url'))
    return {'url': url}

if __name__ == '__main__':
    app.run()

